def reach(evlist):
    adj={}
    for u,v,t in evlist: adj.setdefault(u,[]).append((t,v))
    for k in adj: adj[k].sort()
    earliest={}; q=[]
    for t,v in adj.get(1006,[]):
        if t<earliest.get(v,1e18): earliest[v]=t; q.append((v,t))
    while q:
        u,ta=q.pop()
        if earliest.get(u,1e18)<ta: continue
        for t,v in adj.get(u,[]):
            if t<ta: continue
            if t>ta+D: break
            if v!=1006 and t<earliest.get(v,1e18): earliest[v]=t; q.append((v,t))
    return 1860 in earliest
